'use strict';
// Thought experiments for WikiFeed – English version of thoughts.js.
// Same ids, same order, same answer positions as the German file, so answers carry over between languages.

const THINK_FIELDS_EN = {
  ethik: { label: 'Ethics & morality', axis: ['Outcomes matter', 'Principles matter'] },
  geist: { label: 'Consciousness & mind', axis: ['Mind is physics', 'Consciousness is more'] },
  ich: { label: 'Identity & self', axis: ['Matter & origin count', 'Pattern & memory count'] },
  physik: { label: 'Physics' },
  logik: { label: 'Logic & mathematics' },
  wahl: { label: 'Decisions & game theory' },
  wissen: { label: 'Knowledge & reality' },
};

const THOUGHTS_EN = [
  // ---------------- Ethics & morality ----------------
  { id: 'trolley', icon: '🚋', field: 'ethik', title: 'The Trolley Problem', wiki: 'Trolley problem',
    text: 'A runaway tram is hurtling towards five track workers. You are standing at a switch. If you pull the lever, the tram turns onto a side track – but a single worker is standing there and will die.',
    q: 'Do you pull the lever?',
    opts: [['Yes, I pull it', -1], ['No, I do not intervene', 1]],
    args: [['For', 'Five lives outweigh one. Doing nothing is a decision too – just the one with the worse result.'],
      ['Against', 'There is a difference between letting someone die and killing them. The one worker would never have been in danger without you, and you may not treat him as a figure in a sum.']],
    twist: { text: 'New situation: you are on a bridge above the track. Next to you stands a very heavy man. If you push him off, his body stops the tram – he dies, the five survive.',
      q: 'Do you push him?', opts: [['Yes', -1], ['No', 1]],
      note: 'The sum is the same: one against five. Yet most people hesitate far more here. This gap between calculation and feeling is what made the problem famous.' },
    info: 'The switch version comes from the British philosopher Philippa Foot (1967), the bridge variant from Judith Jarvis Thomson. Today the question is back in the debate about how self-driving cars should decide in an unavoidable accident.' },

  { id: 'teich', icon: '🌊', field: 'ethik', title: 'The Child in the Pond', wiki: 'Peter Singer',
    text: 'On your way to work you see a small child about to drown in a shallow pond. You could easily save it, but your new, expensive shoes would be ruined. Nobody else is around.',
    q: 'Do you have to wade in?',
    opts: ['Yes, of course', 'No, that is optional'],
    args: [['The real point', 'Almost everyone says: of course I must. A pair of shoes is nothing compared with a life. The philosopher Peter Singer concludes: then you must also donate when the same amount can save a child far away.'],
      ['The objection', 'Closeness makes a difference. At the pond only you are there; with a donation millions could help. And a duty that never ends asks too much of anyone.']],
    twist: { text: 'The child is not in front of you but 4,000 miles away. The price of your shoes would be enough to protect it from a deadly disease.',
      q: 'Are you just as obliged?', opts: ['Yes, distance changes nothing', 'No, that is different'],
      note: 'Singer says distance is morally irrelevant. Anyone who disagrees has to explain why miles make a life worth less.' },
    info: 'The example comes from Peter Singer’s essay “Famine, Affluence, and Morality” (1972). It is one of the most influential texts in modern ethics and a starting point of the “effective altruism” movement.' },

  { id: 'schleier', icon: '🎭', field: 'ethik', title: 'The Veil of Ignorance', wiki: 'Veil of ignorance',
    text: 'You get to set the rules of a new society: taxes, wages, rights. The catch: you do not know who you will be in it. Rich or poor, healthy or ill, gifted or not – that is drawn by lot afterwards.',
    q: 'Which society do you choose?',
    opts: ['One where the poorest are as well off as possible', 'One with the highest average, even if some have little', 'One with big chances to win and big risk'],
    args: [['Rawls’s answer', 'If you do not know where you will end up, you protect yourself against the worst case. Inequality is only just if it also benefits the weakest.'],
      ['The objection', 'That assumes everyone is extremely cautious. Someone who likes a little risk would choose the highest average – and ends up with utilitarianism.']],
    info: 'The American philosopher John Rawls introduced the thought experiment in “A Theory of Justice” (1971). The idea behind it: fair rules are the ones you would agree to before knowing your own advantage.' },

  { id: 'gyges', icon: '💍', field: 'ethik', title: 'The Ring of Gyges', wiki: 'Ring of Gyges',
    text: 'A shepherd finds a ring that makes him invisible whenever he turns it. Nobody can ever catch him. He seduces the queen, kills the king and takes power.',
    q: 'Would you still be just with such a ring?',
    opts: ['Yes, I would stay decent', 'No, sooner or later not', 'At first yes, in the long run I do not know'],
    args: [['Glaucon’s claim', 'Nobody is just by choice. We follow rules because we fear punishment and a bad reputation. Take that away, and the just person acts like the unjust one.'],
      ['Plato’s reply', 'Whoever does wrong harms himself: his soul falls into disorder and he becomes a slave to his desires. Justice pays off even when nobody is watching.']],
    info: 'Glaucon tells the story in the second book of Plato’s “Republic” (around 375 BC). It asks whether morality is more than the fear of being caught – and it fits everything people do anonymously online.' },

  { id: 'karneades', icon: '🪵', field: 'ethik', title: 'The Plank of Carneades', wiki: 'Plank of Carneades',
    text: 'Two shipwrecked sailors are drifting in the sea. There is only one plank, and it carries only one person. One of them reaches it first. The other pushes him off, saves himself, and the first one drowns.',
    q: 'Did the second man do wrong?',
    opts: ['Yes, that was killing', 'No, that does not apply in mortal danger', 'Wrong, yes, but not punishable'],
    args: [['It remains wrong', 'The first man had done nothing wrong. His life was worth just as much, and nobody may kill an innocent person to save himself.'],
      ['Nobody can demand more', 'No law can require a person to die voluntarily. Someone fighting for his life is not acting freely but out of sheer necessity.']],
    info: 'The example is attributed to the Greek philosopher Carneades (2nd century BC). German criminal law follows the third answer: the act is unlawful but may go unpunished as an “excusing necessity”.' },

  { id: 'omelas', icon: '🏙️', field: 'ethik', title: 'The City of Omelas', wiki: 'The Ones Who Walk Away from Omelas',
    text: 'Omelas is a perfectly happy city: no war, no poverty, everyone is healthy and content. But this happiness depends on one condition. In a cellar a single child must live in misery. If it is freed, everyone’s happiness ends.',
    q: 'What do you do when you find out?',
    opts: [['I stay – the happiness of so many weighs more', -1], ['I walk away', 1], ['I free the child', 1]],
    args: [['For staying', 'Thousands live happily, one suffers. Any other world would be worse in total. Our own prosperity also rests on the suffering of others.'],
      ['Against', 'Happiness built on the torment of an innocent is worth nothing. Some things must not be done, no matter how much comes out of them.']],
    info: 'Ursula K. Le Guin wrote the short story “The Ones Who Walk Away from Omelas” in 1973. It is considered one of the sharpest challenges to utilitarianism, which judges actions only by the sum of happiness.' },

  { id: 'luege', icon: '🚪', field: 'ethik', title: 'The Murderer at the Door', wiki: 'On a Supposed Right to Tell Lies from Benevolent Motives',
    text: 'Your friend is fleeing from a murderer and hides in your house. Shortly afterwards the murderer knocks and asks you whether your friend is with you. Staying silent is not possible – you have to answer.',
    q: 'May you lie?',
    opts: [['Yes, obviously', -1], ['No, lying is always wrong', 1]],
    args: [['For the lie', 'Here the truth helps a murderer. A rule that leads to such a result cannot be right. The murderer has no claim on your honesty.'],
      ['Kant’s reply', 'Whoever lies makes himself responsible for everything that follows. Above all: if lying is allowed whenever it seems useful, nobody can rely on anyone’s word any more.']],
    info: 'Immanuel Kant really did defend the strict ban on lying in 1797, in reply to the Frenchman Benjamin Constant. Hardly any of his claims is criticised as fiercely to this day, even by Kantians.' },

  // ---------------- Consciousness & mind ----------------
  { id: 'mary', icon: '🎨', field: 'geist', title: 'Mary’s Room', wiki: 'Knowledge argument',
    text: 'Mary is the best colour scientist in the world. She knows everything physics and brain science can say about colours. But she has spent her whole life in a black-and-white room and has never seen a colour. One day she walks out and sees a red tomato.',
    q: 'Does Mary learn something new at that moment?',
    opts: [['Yes – what red looks like', 1], ['No, she already knew everything', -1]],
    args: [['Yes', 'She finds out what it feels like to see red. That was in no book. So there are facts about experience that physics does not capture.'],
      ['No', 'Mary gains no new knowledge but a new ability: recognising and imagining red. Or she merely gets to know an old fact in a new way.']],
    info: 'The Australian philosopher Frank Jackson published the thought experiment in 1982 as an argument against physicalism. Later he changed sides himself and now considers his own argument mistaken.' },

  { id: 'china', icon: '🀄', field: 'geist', title: 'The Chinese Room', wiki: 'Chinese room',
    text: 'You are sitting in a closed room and do not speak a word of Chinese. Slips of paper with Chinese characters come in through a slot. Using a thick rule book (“answer these characters with those”) you write replies. Outside, people are convinced they are talking to a Chinese speaker.',
    q: 'Does anyone here understand Chinese?',
    opts: [['No, nobody', 1], ['Yes – the whole system of room, book and person', -1]],
    args: [['Searle’s point', 'You only shuffle symbols according to rules without knowing what they mean. That is exactly what a computer does. Following rules is not yet understanding.'],
      ['The systems reply', 'You are only a component, just as a single nerve cell does not understand English. The understanding lies in the system as a whole, not in you.']],
    info: 'John Searle put forward the argument in 1980 against the idea that a correctly programmed computer has a mind. Since language models that answer fluently exist, it is debated as fiercely as on day one.' },

  { id: 'zombie', icon: '🧟', field: 'geist', title: 'The Philosophical Zombie', wiki: 'Philosophical zombie',
    text: 'Imagine a being identical to you atom for atom. It talks, laughs and cries “ouch!” when it bumps into something. But inside everything is dark: it experiences nothing, feels nothing, nobody is home.',
    q: 'Is such a being even conceivable?',
    opts: [['Yes, it is imaginable', 1], ['No, it is a contradiction', -1]],
    args: [['Yes', 'If it is conceivable, then experience does not follow necessarily from the body. Consciousness would be something extra that physics alone does not explain.'],
      ['No', 'We only believe we can imagine it. A being with exactly your brain would also claim to be conscious – for the same reasons you do.']],
    info: 'The idea was made famous by the Australian philosopher David Chalmers in the 1990s. It belongs to his “hard problem of consciousness”: why does information processing feel like anything at all?' },

  { id: 'fledermaus', icon: '🦇', field: 'geist', title: 'What Is It Like to Be a Bat?', wiki: 'What Is It Like to Be a Bat?',
    text: 'Bats find their way by echolocation: they call out and “see” with the echo. Suppose science one day knows everything about their brain, every cell and every circuit.',
    q: 'Would we then know what it feels like to be a bat?',
    opts: [['No, that stays closed to us', 1], ['Yes, in principle', -1]],
    args: [['No', 'Science describes from the outside. Experience exists only from the inside. At best we can imagine what it would be like for us to hang from the ceiling – not what it is like for the bat.'],
      ['Yes', 'Colours or heat were once thought inexplicable too. With enough knowledge the experience might be reconstructed or translated into our own.']],
    info: 'Thomas Nagel’s essay “What Is It Like to Be a Bat?” (1974) is one of the most cited texts in the philosophy of mind. Nagel chose bats because they are close enough to us to have experience and alien enough for us not to know it.' },

  { id: 'spektrum', icon: '🌈', field: 'geist', title: 'The Inverted Spectrum', wiki: 'Inverted spectrum',
    text: 'Perhaps you inwardly see red where I see green. We would both have learned to call tomatoes “red” and grass “green”, and would behave the same in every test. The difference would lie only in the experience.',
    q: 'Could anyone ever find out?',
    opts: ['No, never', 'Yes, through the brain', 'The question makes no sense'],
    args: [['No', 'Every test only checks behaviour and words. Inner experience itself cannot be laid side by side and compared.'],
      ['Yes', 'Colours are related: red seems warm, yellow is bright, there are more distinguishable shades of red than of yellow. A swap would give itself away in these relations.']],
    info: 'The idea is already found in John Locke in 1690. To this day it is a touchstone for any theory that wants to explain consciousness through function and behaviour alone.' },

  { id: 'turing', icon: '🤖', field: 'geist', title: 'The Turing Test', wiki: 'Turing test',
    text: 'You chat for five minutes with two strangers. One is a human, the other a machine. At the end you cannot say, try as you might, which is which.',
    q: 'Can this machine think?',
    opts: [['Yes, then it thinks', -1], ['No, it only pretends', 1]],
    args: [['Yes', 'With humans, too, we only infer a mind from behaviour. Anyone who demands more from the machine is applying a double standard.'],
      ['No', 'Deceiving is not thinking. A program can produce answers without understanding or experiencing anything – see the Chinese room.']],
    info: 'Alan Turing proposed the “imitation game” in 1950 to replace the vague question “Can machines think?” with a test. Today’s language models often pass such tests – and what that means is an open debate.' },

  // ---------------- Identity & self ----------------
  { id: 'theseus', icon: '⛵', field: 'ich', title: 'The Ship of Theseus', wiki: 'Ship of Theseus',
    text: 'The Athenians keep the ship of the hero Theseus in the harbour. Every year they replace a rotten plank with a new one. After many years not a single part of the original ship is left.',
    q: 'Is it still the ship of Theseus?',
    opts: [['Yes, it is the same ship', 1], ['No, it is a replica', -1], 'From some plank onwards it no longer is'],
    args: [['Yes', 'Shape, purpose and an unbroken history are preserved. A river also stays the same although new water keeps flowing.'],
      ['No', 'A thing is its material. If nothing of the original is left, you have a copy, even if it lies in the same place.']],
    twist: { text: 'Someone has secretly collected all the old planks and rebuilt a ship from them in a shipyard. Now there are two.',
      q: 'Which one is the real one?', opts: [['The one in the harbour', 1], ['The one made of the old planks', -1], 'Both or neither'],
      note: 'This sharpening comes from Thomas Hobbes. It shows that “the same” can mean two things: the same material or the same continuous history.' },
    info: 'The puzzle was handed down by the Greek writer Plutarch. It concerns you too: most of the cells in your body are replaced over the years. Are you still the same person you were as a child?' },

  { id: 'teleporter', icon: '🛸', field: 'ich', title: 'The Teleporter', wiki: 'Teletransportation paradox',
    text: 'A machine scans your body down to the last atom and destroys it in the process. The data goes to Mars, where an exact copy is built from new material. It has all your memories and feels like you.',
    q: 'Do you step in?',
    opts: [['Yes, that is me on Mars', 1], ['No, I die and someone else lives on', -1]],
    args: [['Step in', 'What makes you you are your memories, your character, your plans. All of that arrives. There is nothing more of “you” to save.'],
      ['Do not step in', 'For you it goes dark. That someone with your memories wakes up afterwards does not help you – no more than a twin would.']],
    twist: { text: 'The machine has a fault: your body on Earth is not destroyed. Now there are two of you.',
      q: 'Which of the two are you?', opts: ['The one on Earth', 'Both', 'The question has no answer'],
      note: 'Derek Parfit drew a radical conclusion: the question “Is that still me?” matters less than we think. What counts is that someone with my memories and goals lives on.' },
    info: 'The thought experiment appears in Derek Parfit’s book “Reasons and Persons” (1984). Parfit wrote that the insight took away much of his fear of death.' },

  { id: 'sumpfmann', icon: '⚡', field: 'ich', title: 'Swampman', wiki: 'Swampman',
    text: 'A man walks through a swamp and is killed by lightning. At the same instant a second bolt, by pure chance, forms an exact copy of him out of swamp matter. It goes home, greets his family and carries on writing his book.',
    q: 'Is Swampman the same person?',
    opts: [['Yes, he is identical in everything', 1], ['No, he lacks the past', -1]],
    args: [['Yes', 'Nobody, not even he himself, can detect a difference. A difference that changes nothing is no difference.'],
      ['No', 'He “remembers” things he never experienced. He does not recognise his friends, for he has never seen them before. His thoughts have no history to refer to.']],
    info: 'The American philosopher Donald Davidson invented Swampman in 1987. He wanted to show that the meaning of our thoughts depends on how we acquired them over the course of our lives.' },

  // ---------------- Physics ----------------
  { id: 'maxwell', icon: '😈', field: 'physik', title: 'Maxwell’s Demon', wiki: 'Maxwell\'s demon',
    text: 'A box full of gas is divided by a wall. In the wall there is a tiny flap guarded by a demon. He lets fast particles pass only to the right and slow ones only to the left. Soon it is hot on the right and cold on the left, without any work being done.',
    q: 'Can the demon trick the laws of nature this way?',
    opts: ['Yes, in principle', 'No, he pays for it somewhere'],
    correct: 1,
    args: [['Why it is tempting', 'Energy could be drawn from the temperature difference – a perpetual motion machine. That would contradict the second law of thermodynamics, according to which disorder never decreases by itself.'],
      ['The solution', 'The demon has to remember which particle is how fast. At some point his memory is full and he has to erase it. Erasing information inevitably produces heat – at least as much as he saved before.']],
    info: 'James Clerk Maxwell invented the demon in 1867. The resolution took more than a hundred years (Szilárd 1929, Landauer 1961, Bennett 1982) and revealed something deep: information is physical.' },

  { id: 'katze', icon: '🐱', field: 'physik', title: 'Schrödinger’s Cat', wiki: 'Schrödinger\'s cat',
    text: 'A cat sits in a sealed box. Inside is a single radioactive atom. If it decays, it triggers a mechanism that releases poison. By the rules of quantum physics the atom is, after one hour, in a superposition: decayed and not decayed at once.',
    q: 'What about the cat before anyone looks?',
    opts: ['Dead and alive at once', 'Either dead or alive, we just do not know', 'Both – in separate worlds'],
    args: [['Schrödinger’s intention', 'He wanted to show how absurd it gets when quantum rules are simply carried over to large things. He considered a half-dead cat nonsense.'],
      ['Today’s view', 'The cat is never truly isolated: air, heat and the box itself constantly “measure” along. As a result the superposition vanishes within tiny fractions of a second. This is called decoherence.']],
    twist: { text: 'A friend opens the box and looks – but he himself is in a sealed laboratory, and you are waiting outside the door.',
      q: 'Is the friend now in a superposition for you?', opts: ['Yes, until I open the door', 'No, his look settled it'],
      note: 'This is “Wigner’s friend” (1961). It asks the uncomfortable question of what a measurement actually is and whether it needs a consciousness. There is still no agreement.' },
    info: 'Erwin Schrödinger described the thought experiment in 1935. Which interpretation of quantum physics is right – Copenhagen, many-worlds or another – remains open. The calculations are the same for all of them.' },

  { id: 'zwillinge', icon: '👯', field: 'physik', title: 'The Twin Paradox', wiki: 'Twin paradox',
    text: 'Anna and Ben are twins. Anna flies at nearly the speed of light to a distant star and comes back. Ben stays on Earth. According to relativity, time passes more slowly for moving clocks. But from Anna’s point of view it was Ben who moved.',
    q: 'Who is younger when they meet again?',
    opts: ['Anna, the traveller', 'Ben, who stayed at home', 'Both are the same age'],
    correct: 0,
    args: [['The explanation', 'The situation is not symmetrical. Anna has to turn around at the star, that is, slow down and accelerate again. She changes her frame of reference; Ben does not. So it is clearly she for whom less time has passed.'],
      ['Has this been measured?', 'Yes. Atomic clocks flown in aeroplanes run measurably differently after landing from clocks on the ground. GPS, too, would be off by miles within a short time without these corrections.']],
    info: 'The puzzle goes back to Einstein’s special theory of relativity of 1905; the twins were introduced by Paul Langevin in 1911. It is not a real contradiction, just a consequence that defies everyday intuition.' },

  { id: 'laplace', icon: '🔮', field: 'physik', title: 'Laplace’s Demon', wiki: 'Laplace\'s demon',
    text: 'Imagine a mind that at one instant knows the position and velocity of every particle in the universe, along with all laws of nature. Nothing would be uncertain to it. It could compute the entire future and past.',
    q: 'So is the future already fixed?',
    opts: ['Yes, everything is fixed', 'No, there is genuine chance', 'Fixed perhaps, but never computable'],
    args: [['For', 'If every event has a cause, the next state follows necessarily from the present one. Your decisions, too, would then just be processes in the brain.'],
      ['Against', 'Quantum physics knows genuine chance: when an atom decays cannot be predicted in principle. And even the tiniest measurement errors grow like an avalanche in many systems (chaos).']],
    info: 'Pierre-Simon Laplace described this idea in 1814. It sums up the world view of classical physics and sits at the centre of the question whether there can be free will.' },

  { id: 'galilei', icon: '🪨', field: 'physik', title: 'Galileo’s Falling Stones', wiki: 'Galileo\'s Leaning Tower of Pisa experiment',
    text: 'For almost 2,000 years Aristotle’s teaching held: heavy things fall faster than light ones. Galileo wondered: what happens if you tie a heavy and a light stone together with a string and drop them? (Without air resistance.)',
    q: 'How does the pair fall compared with the heavy stone alone?',
    opts: ['Faster, it is heavier after all', 'Slower, the light one brakes it', 'Exactly as fast'],
    correct: 2,
    args: [['The contradiction', 'According to Aristotle the light stone should slow the heavy one down, so the pair would fall more slowly. At the same time the pair is heavier than the heavy stone alone, so it should fall faster. Both cannot be true.'],
      ['The solution', 'The contradiction only disappears if all bodies fall at the same speed. Galileo arrived at this by pure thought, without any experiment.']],
    info: 'The argument appears in Galileo’s “Discorsi” of 1638. The most beautiful proof was delivered in 1971 by astronaut David Scott on the Moon: hammer and feather landed at the same instant.' },

  { id: 'aufzug', icon: '🛗', field: 'physik', title: 'Einstein’s Elevator', wiki: 'Equivalence principle',
    text: 'You wake up in a windowless cabin. You feel your normal weight; a ball you let go of falls to the floor. There are two possibilities: the cabin is standing on Earth. Or it is being accelerated steadily upwards by a rocket in empty space.',
    q: 'Can you find out from inside which is true?',
    opts: ['Yes, with a clever experiment', 'No, it cannot be told apart'],
    correct: 1,
    args: [['The explanation', 'No experiment inside the cabin can show the difference. Gravity and acceleration act in exactly the same way on the spot. This is the equivalence principle.'],
      ['The consequence', 'In the accelerated cabin a beam of light would follow a slightly curved path. So gravity must bend light too. In 1919 this was confirmed during a solar eclipse.']],
    info: 'Einstein called the idea from 1907 “the happiest thought of my life”. From it he developed, over eight years, the general theory of relativity, in which gravity is curved spacetime.' },

  { id: 'olbers', icon: '🌌', field: 'physik', title: 'Why Is the Night Dark?', wiki: 'Olbers\'s paradox',
    text: 'Suppose the universe is infinitely large, infinitely old and evenly filled with stars everywhere. Then your line of sight would hit a star in every direction sooner or later. The whole sky would have to shine as brightly as the surface of the Sun.',
    q: 'Why is it dark at night anyway?',
    opts: ['Dust swallows the light', 'The universe had a beginning', 'The stars are simply too far away'],
    correct: 1,
    args: [['The solution', 'The universe is about 13.8 billion years old. We only see stars whose light has had time to reach us. In addition space is expanding and stretches the light of distant galaxies into the invisible.'],
      ['Why dust does not help', 'Dust that swallowed light forever would heat up and eventually glow as brightly as the stars themselves.']],
    info: 'The puzzle is named after the Bremen physician and astronomer Heinrich Wilhelm Olbers (1823). The simple observation that it gets dark at night is thus a hint of the Big Bang.' },

  { id: 'fermi', icon: '👽', field: 'physik', title: 'The Fermi Paradox', wiki: 'Fermi paradox',
    text: 'Our galaxy alone has hundreds of billions of stars, many with planets and billions of years older than the Sun. A civilisation spreading only slowly could have settled the whole Milky Way long ago. Yet we see and hear nothing.',
    q: 'Where is everybody?',
    opts: ['They do not exist, we are alone', 'They exist, but too far away', 'Civilisations wipe themselves out before they travel', 'They are here and do not show themselves'],
    args: [['The “Great Filter”', 'Some step from dead matter to star travel must be extremely unlikely. If it lies behind us (the origin of life, say), we were lucky. If it lies ahead of us, that is not good news.'],
      ['Sober answers', 'Space is unimaginably vast, journeys take tens of thousands of years, and we have only been listening for a few decades. Silence proves little so far.']],
    info: 'The physicist Enrico Fermi is said to have asked over lunch in 1950: “Where is everybody?” To this day there is no accepted answer.' },

  { id: 'grossvater', icon: '⏳', field: 'physik', title: 'The Grandfather Paradox', wiki: 'Grandfather paradox',
    text: 'You travel into the past with a time machine and prevent your grandfather from meeting your grandmother. Then your father is never born – and neither are you. But then who travelled back?',
    q: 'What follows from this?',
    opts: ['Time travel into the past is impossible', 'You can travel but change nothing', 'A new, second timeline is created'],
    args: [['Nothing can be changed', 'By the principle of self-consistency only what fits the known history can happen. Your attempt fails, perhaps in exactly the way that leads to their meeting.'],
      ['Many worlds', 'You land in another branch of reality. There you are never born, but your own origin remains untouched.']],
    info: 'The paradox comes from the science fiction of the 1930s and 1940s. Physics does not clearly rule out time travel into the past; Stephen Hawking, however, suspected that nature prevents it in principle.' },

  // ---------------- Logic & mathematics ----------------
  { id: 'ziege', icon: '🐐', field: 'logik', title: 'The Monty Hall Problem', wiki: 'Monty Hall problem',
    text: 'In a game show there are three doors. Behind one is a car, behind each of the others a goat. You choose door 1. The host, who knows where the car is, opens door 3: a goat. Then he offers you the chance to switch to door 2.',
    q: 'Should you switch?',
    opts: ['Yes, switch', 'No, stay with door 1', 'It does not matter, it is 50:50'],
    correct: 0,
    args: [['The maths', 'Your first choice is right with probability 1/3. Opening a goat door does not change that. The remaining 2/3 now sit entirely on the other door. Switching therefore doubles your chance.'],
      ['To make it click', 'Imagine 100 doors. You pick one, the host opens 98 goat doors and leaves exactly one closed. Would you still stay with yours?']],
    info: 'The puzzle became famous in 1990 through the columnist Marilyn vos Savant. She gave the right answer and received around 10,000 letters of protest, many from mathematicians who were wrong.' },

  { id: 'geburtstag', icon: '🎂', field: 'logik', title: 'The Birthday Paradox', wiki: 'Birthday problem',
    text: 'A party has randomly assembled guests. You wonder: how many people must be in the room for there to be a better than 50 per cent chance that two of them share a birthday?',
    q: 'How many guests does it take?',
    opts: ['23', '57', '183', '366'],
    correct: 0,
    args: [['The explanation', 'The point is not that someone shares your birthday, but that any two share one. With 23 people there are already 253 possible pairs. That is enough for 50.7 per cent.'],
      ['Even more surprising', 'With 57 guests the probability is already above 99 per cent. Only for “someone has my birthday” would you need 253 people.']],
    info: 'The birthday paradox is not a real contradiction; it just shows how poor our feel for probabilities is. In cryptography the “birthday attack” exploits exactly this effect.' },

  { id: 'hilbert', icon: '🏨', field: 'logik', title: 'Hilbert’s Hotel', wiki: 'Hilbert\'s paradox of the Grand Hotel',
    text: 'A hotel has infinitely many rooms: number 1, 2, 3 and so on forever. All rooms are occupied. Late at night a new guest comes to reception and asks for a room.',
    q: 'Does he get one?',
    opts: ['Yes', 'No, full is full'],
    correct: 0,
    args: [['How it works', 'Every guest moves one room along: from 1 to 2, from 2 to 3 and so on. Because there is no last room, everyone finds a place and room 1 becomes free.'],
      ['What it shows', 'With infinite sets “full” no longer means what we are used to. Infinity plus one is just as large as infinity.']],
    twist: { text: 'Now a bus with infinitely many new guests pulls up in front of the fully occupied hotel.',
      q: 'Do they all find room too?', opts: ['Yes', 'No, that is too many'],
      note: 'Yes. Every guest moves to the room with double the number: from 1 to 2, from 2 to 4, from 3 to 6. Afterwards all odd-numbered rooms are free, and there are infinitely many of those.' },
    info: 'David Hilbert told the example in a lecture in 1924 to illustrate Georg Cantor’s theory of the infinite. Cantor also showed that there are infinities of different sizes.' },

  { id: 'achilles', icon: '🐢', field: 'logik', title: 'Achilles and the Tortoise', wiki: 'Zeno\'s paradoxes',
    text: 'Swift Achilles races a tortoise and gives it a head start. By the time he reaches its starting point, it has moved on a little. By the time he gets there, it is again a little further. And so on, infinitely often.',
    q: 'Does Achilles ever catch up?',
    opts: ['Yes, of course', 'No, he only gets ever closer'],
    correct: 0,
    args: [['The trick', 'Zeno splits a finite distance into infinitely many pieces. He tacitly concludes that infinitely many steps would take infinitely long.'],
      ['The solution', 'The pieces get shorter and shorter, and their sum is finite. If Achilles needs 10 seconds for the first piece, 1 for the next, then 0.1 – the total is only a little over 11 seconds.']],
    info: 'Zeno of Elea devised the paradox around 450 BC to show that motion is an illusion. It could only be resolved cleanly more than 2,000 years later with the concept of a limit.' },

  { id: 'luegner', icon: '🤥', field: 'logik', title: 'The Liar Paradox', wiki: 'Liar paradox',
    text: 'Consider this one sentence: “This sentence is false.” If it is true, then what it says holds – so it is false. If it is false, then what it says does not hold – so it is true.',
    q: 'What is the sentence?',
    opts: ['True', 'False', 'Neither true nor false', 'Both at once'],
    args: [['Neither', 'Not every sentence that looks like a statement states something. A sentence that speaks only about its own truth hangs in the air.'],
      ['The strict solution', 'The logician Alfred Tarski separated levels of language: a sentence may not judge its own truth. “True” belongs to a language above the language.']],
    twist: { text: 'In a village the barber shaves exactly those men who do not shave themselves.',
      q: 'Does the barber shave himself?', opts: ['Yes', 'No', 'Such a barber cannot exist'],
      note: 'If he shaves himself, he should not; if he does not, he should. Such a barber simply cannot exist. In 1901 Bertrand Russell used the same pattern to show that the set theory of the time was contradictory.' },
    info: 'The paradox has been known since antiquity (Eubulides, 4th century BC). In 1931 Kurt Gödel built his incompleteness theorem on a related idea: in every sufficiently rich system of arithmetic there are true sentences that cannot be proved within it.' },

  { id: 'haufen', icon: '🏜️', field: 'logik', title: 'The Paradox of the Heap', wiki: 'Sorites paradox',
    text: 'A million grains of sand are a heap. If you take away a single grain, it remains a heap – one grain makes no difference. That holds at every step. So in the end even a single grain would still have to be a heap.',
    q: 'Where is the mistake?',
    opts: ['There is an exact boundary, we just do not know it', '“Heap” is vague, there is no boundary', 'Strictly speaking there are no heaps at all'],
    args: [['A sharp boundary', 'Perhaps it really does tip at one particular grain. That we cannot point to the spot does not mean it is not there.'],
      ['Vague concepts', 'Words like “heap”, “tall” or “bald” have grey areas. In the middle the statement is neither clearly true nor clearly false, only partly so.']],
    info: 'The puzzle comes from Eubulides of Miletus (4th century BC) and is also called the sorites paradox. It lurks in many real disputes: from when is someone an adult, poor or ill?' },

  { id: 'affen', icon: '🐒', field: 'logik', title: 'The Monkey at the Typewriter', wiki: 'Infinite monkey theorem',
    text: 'A monkey hits the keys of a typewriter completely at random. It never tires and has infinite time.',
    q: 'Will it eventually type the complete “Hamlet”?',
    opts: ['Yes, that is certain', 'No, that never happens'],
    correct: 0,
    args: [['The mathematics', 'Every sequence of characters has a tiny but fixed chance. With infinitely many attempts it occurs with probability 1 at some point – even infinitely often.'],
      ['The reality', 'Even for a single sentence the monkey would need, on average, unimaginably longer than the age of the universe. “Infinite” is simply far more than “a very long time”.']],
    info: 'The idea goes back to the French mathematician Émile Borel (1913). In 2003 real monkeys were given a keyboard in their enclosure: they typed five pages, almost entirely the letter S, and broke the keyboard.' },

  { id: 'hinrichtung', icon: '📅', field: 'logik', title: 'The Unexpected Hanging', wiki: 'Unexpected hanging paradox',
    text: 'A judge says: “You will be executed at noon on a weekday next week, and it will be a surprise.” The prisoner reasons: Friday is out, otherwise I would know on Thursday evening. Then Thursday drops out too, then Wednesday – so it cannot happen at all. On Wednesday the hangman arrives. A complete surprise.',
    q: 'Where is the flaw in the reasoning?',
    opts: ['Already at Friday', 'Only at the earlier days', 'The announcement contradicts itself'],
    args: [['Already at Friday', 'The prisoner assumes the announcement is true. As soon as he concludes that it cannot happen, he no longer believes it – and can be surprised again.'],
      ['Knowing about knowing', 'The puzzle turns on what one can know about one’s own future knowledge. Such self-reference is as treacherous as in the liar sentence.']],
    info: 'The paradox emerged in the 1940s. To this day there is no solution logicians agree on – only around a hundred academic papers with different proposals.' },

  { id: 'dornroeschen', icon: '😴', field: 'logik', title: 'The Sleeping Beauty Problem', wiki: 'Sleeping Beauty problem',
    text: 'Sleeping Beauty is put to sleep on Sunday. Then a coin is tossed. On heads she is woken only on Monday. On tails she is woken on Monday and on Tuesday, but her memory is erased in between. She wakes up and does not know what day it is.',
    q: 'From her point of view, how likely is it that the coin shows heads?',
    opts: ['1/2', '1/3'],
    args: [['For 1/2', 'The coin is fair, and on waking Sleeping Beauty learns nothing new. She knew beforehand that she would wake up.'],
      ['For 1/3', 'If the experiment is repeated often, two thirds of all awakenings fall on “tails”. Anyone who had to bet at every awakening should bet on tails.']],
    info: 'The problem became known in 2000 through the philosopher Adam Elga. Experts are still divided into “halfers” and “thirders” – both with good arguments.' },

  // ---------------- Decisions & game theory ----------------
  { id: 'gefangene', icon: '⛓️', field: 'wahl', title: 'The Prisoner’s Dilemma', wiki: 'Prisoner\'s dilemma',
    text: 'You and an accomplice are in separate cells. If you both stay silent, each gets 1 year. If only you betray him, you go free and he gets 10 years – and vice versa. If you betray each other, each gets 5 years. You cannot confer.',
    q: 'What do you do?',
    opts: ['I stay silent', 'I betray him'],
    args: [['Betrayal is “logical”', 'Whatever the other does, betraying is better for you. If he stays silent, you go free instead of serving 1 year. If he betrays, you get 5 instead of 10.'],
      ['And yet worse', 'If both think this way, each gets 5 years instead of just 1 year for mutual silence. Sensible action by each individual leads to the worse result for all.']],
    twist: { text: 'You do not play the same game once but a hundred times in a row, and each sees what the other did last time.',
      q: 'Does that change your strategy?', opts: ['Yes, now cooperation pays', 'No, I stick to it'],
      note: 'In computer tournaments a very simple strategy won: “tit for tat”. Be friendly first, then always do what the other did last. Repetition makes trust possible.' },
    info: 'The game was developed at the RAND Corporation in 1950. It explains arms races, price wars and why climate protection is so hard: everyone is better off if the others make the effort.' },

  { id: 'newcomb', icon: '📦', field: 'wahl', title: 'Newcomb’s Problem', wiki: 'Newcomb\'s paradox',
    text: 'Two boxes stand before you. The transparent one contains 1,000 euros. The second is closed. A being that predicts decisions almost always correctly filled it yesterday: with a million if it foresaw that you would take only the closed box – and with nothing if it foresaw that you would take both.',
    q: 'What do you take?',
    opts: ['Only the closed box', 'Both boxes'],
    args: [['Only one', 'Almost everyone who took only the one box is a millionaire. Almost everyone who took both went home with 1,000 euros. You need to know no more.'],
      ['Both', 'The money is already in there or it is not. Your choice cannot change the past. With both boxes you have 1,000 euros more in every case.']],
    info: 'The physicist William Newcomb devised the problem; the philosopher Robert Nozick made it known in 1969. He wrote: almost everyone thinks the answer is obvious – only each a different one.' },

  { id: 'buridan', icon: '🫏', field: 'wahl', title: 'Buridan’s Ass', wiki: 'Buridan\'s ass',
    text: 'A hungry donkey stands exactly halfway between two haystacks. Both are the same size, the same distance away and equally tasty. There is not the slightest reason to prefer one to the other.',
    q: 'What happens to a perfectly rational donkey?',
    opts: ['It starves – no reason, no choice', 'It simply picks one'],
    args: [['It starves', 'Whoever acts only on reasons needs a reason for left or right. If there is none, it stays put. That would be the consequence of a strictly calculable will.'],
      ['It chooses', 'Starving is worse than either haystack. So the rational thing is to choose at random. A good decision-maker knows when brooding costs more than choosing.']],
    info: 'The parable is named after the French philosopher Jean Buridan (14th century) but does not appear in his writings at all. The idea is already in Aristotle. Engineers know the problem from digital circuits that get stuck between 0 and 1.' },

  { id: 'pascal', icon: '🎲', field: 'wahl', title: 'Pascal’s Wager', wiki: 'Pascal\'s wager',
    text: 'Either God exists or not; neither can be proved. If you believe and he exists, you gain eternal happiness. If you believe and he does not exist, you lose little. If you do not believe and he exists, you lose everything.',
    q: 'So is it rational to bet on God?',
    opts: ['Yes, the sums work out', 'No, faith does not work like that'],
    args: [['For', 'An infinite gain beats any finite stake, even if the chance is tiny. Whoever calculates must bet.'],
      ['Against', 'Which god? There are many religions that exclude one another. Besides, you cannot believe at the push of a button, and a god would hardly reward calculating piety.']],
    info: 'Blaise Pascal noted the wager in his “Pensées”, published in 1670 after his death. It is considered one of the first applications of decision theory – to a question it may not be made for.' },

  { id: 'allmende', icon: '🐄', field: 'wahl', title: 'The Tragedy of the Commons', wiki: 'Tragedy of the commons',
    text: 'Ten farmers share a village meadow. Each one thinks: if I put one more cow on it, the profit is mine alone. The damage from the grazed-down grass is spread over all ten.',
    q: 'What happens to the meadow in the long run?',
    opts: ['It is grazed bare', 'The farmers agree in time', 'It takes the state or fences'],
    args: [['The gloomy view', 'For each individual the extra cow always pays. So everyone adds more cows until the meadow is ruined. Freedom in a commons brings ruin to all.'],
      ['The counter-evidence', 'The researcher Elinor Ostrom found villages around the world that have jointly preserved forests, fishing grounds and water for centuries – with their own rules, monitoring and penalties.']],
    info: 'The biologist Garrett Hardin coined the term in 1968. Elinor Ostrom received the Nobel Prize in economics in 2009, the first woman to do so, for showing that the tragedy is not inevitable. The pattern fits overfishing and the climate.' },

  { id: 'ultimatum', icon: '💶', field: 'wahl', title: 'The Ultimatum Game', wiki: 'Ultimatum game',
    text: 'A stranger is given 100 euros and has to offer you a share. If you accept, the money is split that way. If you refuse, neither of you gets anything. There is only this one round, and you will never meet again. He offers you 10 euros and keeps 90.',
    q: 'Do you accept?',
    opts: ['Yes, 10 euros is better than nothing', 'No, that is outrageous'],
    args: [['Accept', 'In pure arithmetic any amount above zero is a gain. Refusing costs you 10 euros and earns you nothing.'],
      ['Refuse', 'People pay a price to punish unfairness. Precisely because everyone knows this, most proposers offer nearly half of their own accord.']],
    info: 'The experiment comes from the German economist Werner Güth (1982). Around the world, offers below about 20 to 30 per cent are very often rejected. It became a key witness against the picture of the purely self-interested human.' },

  { id: 'petersburg', icon: '🪙', field: 'wahl', title: 'The St. Petersburg Game', wiki: 'St. Petersburg paradox',
    text: 'A coin is tossed until heads comes up for the first time. If that happens on the very first toss, you get 2 euros. On the second 4 euros, on the third 8, and so it keeps doubling. Mathematically the average winnings are infinitely large.',
    q: 'How much would you pay to play once?',
    opts: ['At most 20 euros', 'A few hundred euros', 'Everything I own'],
    args: [['The calculation', 'Each stage adds exactly 1 euro to the average: half a chance of 2, a quarter of 4 and so on. Infinitely many stages give infinity.'],
      ['Why hardly anyone pays much anyway', 'The second million makes you less happy than the first. Besides, in half of all games you win only 2 euros, and no bank could ever pay out the giant prizes.']],
    info: 'Nikolaus Bernoulli posed the problem in 1713; his cousin Daniel solved it in St. Petersburg in 1738 with the idea of utility: what matters is what money is worth to you, not the amount. Modern economics builds on this.' },

  // ---------------- Knowledge & reality ----------------
  { id: 'tank', icon: '🧠', field: 'wissen', title: 'The Brain in a Vat', wiki: 'Brain in a vat',
    text: 'Imagine a scientist has removed your brain and placed it in a nutrient solution. A computer feeds in, through cables, exactly the signals that would otherwise come from eyes, ears and skin. Everything you are seeing and feeling right now would be simulated.',
    q: 'Can you know for sure that this is not so?',
    opts: ['No, I cannot prove it', 'Yes, it can be ruled out'],
    args: [['No', 'Every test you can think of would turn out the same in the vat. Experience cannot prove that there is a world behind experience.'],
      ['Yes', 'The philosopher Hilary Putnam argued: a vat brain has never seen real vats. Its words “brain” and “vat” refer only to images in the program. The sentence “I am a brain in a vat” would therefore always be false.']],
    info: 'The modern version comes from Hilary Putnam (1981). It is the remake of René Descartes’ evil demon from 1641 – and the template for the film “The Matrix”.' },

  { id: 'hoehle', icon: '🔥', field: 'wissen', title: 'The Allegory of the Cave', wiki: 'Allegory of the cave',
    text: 'People have been sitting chained in a cave since birth and see only the wall in front of them. Behind them a fire burns and objects are carried past. They take the shadows on the wall for the whole of reality. One of them is freed, climbs up and sees the Sun.',
    q: 'He returns and tells them about it. What happens?',
    opts: ['They believe him and want to get out', 'They laugh at him', 'They get angry and turn on him'],
    args: [['Plato’s answer', 'In the dark the returner sees worse than the others and seems confused. They mock him, and anyone who tried to free them they would gladly kill.'],
      ['What is meant', 'The shadows stand for what we perceive with our senses and take for granted. Knowledge is a laborious climb, and whoever tells others about it makes himself unpopular.']],
    info: 'The allegory appears in the seventh book of Plato’s “Republic”. It alludes to the fate of his teacher Socrates, whom the Athenians sentenced to death in 399 BC.' },

  { id: 'simulation', icon: '💻', field: 'wissen', title: 'The Simulation Hypothesis', wiki: 'Simulation hypothesis',
    text: 'Suppose an advanced civilisation has enough computing power to simulate whole worlds with conscious inhabitants. Then it would presumably run very many of them. So there would be far more simulated minds than real ones.',
    q: 'How likely is it that we live in a simulation?',
    opts: ['Very likely', 'Possible, but unlikely', 'Ruled out', 'It makes no difference to us'],
    args: [['Bostrom’s trilemma', 'One of three statements must be true: almost no civilisation reaches this level. Or almost none wants such simulations. Or we are almost certainly inside one.'],
      ['Objections', 'Nobody knows whether consciousness can be simulated at all. And a claim that cannot be tested by anything explains nothing in the end.']],
    info: 'The Swedish philosopher Nick Bostrom published the argument in 2003. It is the technical version of a very old question already posed by Plato’s cave and Descartes’ demon.' },

  { id: 'erlebnis', icon: '🎧', field: 'wissen', title: 'The Experience Machine', wiki: 'Experience machine',
    text: 'Researchers have built a machine that gives you any experience you wish. You lie in a tank and live a perfectly happy life with success, love and adventure. It feels real in every respect, and you forget that you are plugged in.',
    q: 'Do you plug in for good?',
    opts: ['Yes, happiness is happiness', 'No, I want real life'],
    args: [['Plug in', 'In the end what counts is how life feels. If you never notice the difference, you lose nothing. Many people already spend hours in invented worlds today.'],
      ['Do not plug in', 'We want to actually do things, not just have the feeling of doing them. We want to be someone and live with real people. So more matters than pleasant states.']],
    info: 'Robert Nozick posed the question in “Anarchy, State, and Utopia” (1974). It is aimed at hedonism, the view that only pleasure and well-being count in life.' },

  { id: 'molyneux', icon: '👁️', field: 'wissen', title: 'Molyneux’s Problem', wiki: 'Molyneux\'s problem',
    text: 'A person has been blind from birth. They have learned to tell a sphere from a cube by touch. Now they have an operation and can suddenly see. A sphere and a cube lie on the table in front of them.',
    q: 'Do they recognise the sphere just by looking?',
    opts: ['Yes, immediately', 'No, they have to learn it first'],
    correct: 1,
    args: [['The old conjecture', 'John Locke thought: no. What we see and what we touch are at first two separate worlds. Only experience links them.'],
      ['The finding', 'In 2011 children in India who had been born blind were operated on and tested straight afterwards. They could not match what they saw to what they had touched – but learned to within a few days.']],
    info: 'The Irishman William Molyneux, whose wife had gone blind, posed the question in 1688 in a letter to John Locke. For more than 300 years people could only speculate, until medicine made an experiment possible.' },

  { id: 'gettier', icon: '🕰️', field: 'wissen', title: 'The Stopped Clock', wiki: 'Gettier problem',
    text: 'You look at the station clock: exactly 12 o’clock. So you believe it is 12 o’clock. And it is. What you do not know: the clock stopped yesterday at 12. You happened to look at exactly the right moment.',
    q: 'Did you know that it was 12 o’clock?',
    opts: ['Yes, I was right after all', 'No, that was just luck'],
    args: [['Yes', 'Your belief was true, and you had a good reason: you looked at a clock. More cannot be asked of knowledge.'],
      ['No', 'There was no real connection between your reason and the truth. A minute later you would have been wrong with the same confidence.']],
    info: 'Since Plato, knowledge had been taken to be “justified true belief”. In 1963 Edmund Gettier showed with cases of this kind, in just three pages, that this is not enough. What exactly knowledge is has been open again ever since.' },

  { id: 'teekanne', icon: '🫖', field: 'wissen', title: 'Russell’s Teapot', wiki: 'Russell\'s teapot',
    text: 'Someone claims: between Earth and Mars a small china teapot is orbiting the Sun. It is too small for any telescope. You cannot prove that it does not exist.',
    q: 'Do you therefore have to consider the teapot possible?',
    opts: ['No, whoever claims must provide evidence', 'Yes, as long as it is not refuted'],
    args: [['No', 'Otherwise one would have to take seriously any claim that cleverly evades every test. The burden of proof lies with the one who makes the claim.'],
      ['The objection', 'Nothing at all speaks for a teapot in space; we know how teapots come about. With the big questions the situation is not so clear-cut, so the comparison limps.']],
    info: 'Bertrand Russell wrote the example in 1952 in an essay on the question whether there is a God. It has been quoted ever since whenever someone says: “Prove me wrong, then!”' },
];
